<template>
  <div id="app" class="flex container h-screen w-full">
    <div class="flex container h-screen w-full">
      <SideNav />

      <div class="w-full h-full overflow-y-scroll no-scrollbar">
        <div class="px-5 pt-3 flex items-center">
          <button
            @click="goHome()"
            class="rounded-full p-3 px-4 focus:outline-none hover:bg-lightblue"
          >
            <i class="fas fa-arrow-left text-blue"></i>
          </button>
          <div class="lg:block ml-4">
            <h1 class="text-xl font-bold">Who to follow</h1>
          </div>
        </div>

        <Loader :loading="loading" />

        <div class="flex gap-1 px-5 py-2 border-b border-lighter" role="tablist">
          <button
            v-for="tab in tabs"
            :key="tab.key"
            type="button"
            role="tab"
            :aria-selected="tab.key === activeTab"
            :aria-label="tab.label"
            @click="activeTab = tab.key"
            :class="['flex-1 min-w-0 flex items-center justify-center gap-2 px-3 py-2 rounded-full text-sm transition-colors flat-btn',
                     tab.key === activeTab
                       ? 'bg-lighter text-blue font-bold ring-1 ring-[color:var(--gd-trim)]'
                       : 'text-dark hover:bg-lighter']"
          >
            <NetworkIcon :network="tab.network" size-class="w-5 h-5 shrink-0" />
            <span class="hidden sm:inline truncate">{{ tab.label }}</span>
          </button>
        </div>

        <Users :users="activeProfiles" :loading="loading" />

        <button
          v-if="hasMore && !loading"
          :disabled="loadingMore"
          @click="loadMore()"
          class="p-3 w-full hover:bg-lighter text-center text-blue border-t border-lighter"
        >
          Show More
        </button>
      </div>

      <div
        class="hidden md:block w-1/3 z-0 h-full border-l border-lighter px-6 py-2 overflow-y-scroll no-scrollbar relative"
      >
        <SearchBar />
      </div>
    </div>
  </div>
</template>

<script>
import SideNav from "../components/SideNav.vue";
import SearchBar from "../components/SearchBar.vue";
import Users from "../components/Users.vue";
import Loader from "../components/Loader.vue";
import {warpnetService} from "@/service/service";
import {networkSections, sectionKey} from "@/lib/network";
import NetworkIcon from "@/components/NetworkIcon.vue";

export default {
  name: "WhoToFollow",
  components: {
    SideNav,
    SearchBar,
    Users,
    Loader,
    NetworkIcon,
  },
  data() {
    return {
      loading: true,
      loadingMore: false,
      activeTab: 'warpnet',
      profiles: [],
      cursors: {},
    };
  },
  computed: {
    tabs() {
      return networkSections(this.profiles);
    },
    activeProfiles() {
      return this.profiles.filter((p) => sectionKey(p) === this.activeTab);
    },
    hasMore() {
      return Boolean(this.cursors[this.activeTab]);
    },
  },
  methods: {
    goHome() {
      this.$router.push("/");
    },
    // Each network keeps its own cursor; one that ran out drops out.
    async addPages(pages) {
      const entries = Object.entries(pages);
      // Friends of friends first; the order within each part is the node's.
      const sorted = await Promise.all(entries.map(([, page]) => warpnetService.circleFirst(page.users)));
      const cursors = {...this.cursors};
      entries.forEach(([network, page], i) => {
        for (const p of sorted[i]) {
          if (!this.profiles.some((x) => x.id === p.id)) {
            this.profiles.push(p);
          }
        }
        if (page.cursor) {
          cursors[network] = page.cursor;
        } else {
          delete cursors[network];
        }
      });
      this.cursors = cursors;
    },
    async loadMore() {
      if (!this.hasMore || this.loadingMore) {
        return;
      }
      const network = this.activeTab;
      this.loadingMore = true;
      try {
        await this.addPages(await warpnetService.getWhoToFollow({[network]: this.cursors[network]}));
      } catch (err) {
        console.error("loading component:", this.$options.name, err);
      } finally {
        this.loadingMore = false;
      }
    },
  },
  async created() {
    console.log("loading component:", this.$options.name);
    try {
      await this.addPages(await warpnetService.getWhoToFollow());
    } catch (err) {
      console.error("loading component:", this.$options.name, err);
    } finally {
      this.loading = false;
    }
  },
};
</script>
